const shops=[{name:'Sharma General Store',type:'Groceries & essentials',distance:'0.4 km away',rating:'4.8',logo:'🛒',color:'#dfeee4',products:'650+ products'},{name:'Namma Fresh Mart',type:'Fresh produce & dairy',distance:'0.7 km away',rating:'4.7',logo:'🥕',color:'#ffead5',products:'420+ products'},{name:'Gupta Provision Store',type:'Groceries & household',distance:'1.1 km away',rating:'4.6',logo:'🏪',color:'#e9e1f4',products:'580+ products'}];
const prices=[['Sharma General Store','₹28','0.4 km','Best price'],['Namma Fresh Mart','₹30','0.7 km',''],['Gupta Provision Store','₹27','1.1 km','']];
let cart=[{name:'Tata Salt 1 kg',price:28,qty:1,icon:'🧂'},{name:'Fresh milk 1 L',price:72,qty:1,icon:'🥛'}];
const shopGrid=document.querySelector('#shopGrid'),priceList=document.querySelector('#priceList');
shopGrid.innerHTML=shops.map(s=>`<article class="shop-card"><div class="shop-top"><div class="shop-logo" style="background:${s.color}">${s.logo}</div><div><div class="shop-name">${s.name}</div><div class="shop-type">${s.type}</div></div></div><span class="open">● OPEN</span><div class="shop-meta"><span>★ <b>${s.rating}</b></span><span>⌖ ${s.distance}</span></div><footer><span>${s.products}</span><strong>View shop →</strong></footer></article>`).join('');
priceList.innerHTML=prices.map((p,i)=>`<div class="price-entry ${i===0?'best':''}"><small>${p[0]}</small><b>${p[1]}</b><span>${p[2]} ${p[3]?`· <span class="best-tag">${p[3]}</span>`:''}</span></div>`).join('');
function renderCart(){document.querySelector('#cartItems').innerHTML=cart.map((item,i)=>`<div class="cart-row"><div class="mini-icon">${item.icon}</div><div><strong>${item.name}</strong><small>₹${item.price} each</small></div><div class="qty"><button data-i="${i}" data-action="minus">−</button><b>${item.qty}</b><button data-i="${i}" data-action="plus">+</button></div></div>`).join('');const count=cart.reduce((n,x)=>n+x.qty,0),total=cart.reduce((n,x)=>n+x.price*x.qty,0);document.querySelector('#cartCount').textContent=count;document.querySelector('#cartTotal').textContent='₹'+total;}
renderCart();
document.querySelector('#cartItems').addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let x=cart[b.dataset.i];x.qty=Math.max(1,x.qty+(b.dataset.action==='plus'?1:-1));renderCart()});
const drawer=document.querySelector('#cartDrawer'),backdrop=document.querySelector('#backdrop');document.querySelector('#openCart').onclick=()=>{drawer.classList.add('open');backdrop.classList.add('show')};function close(){drawer.classList.remove('open');backdrop.classList.remove('show')}document.querySelector('#closeCart').onclick=close;backdrop.onclick=close;
function toast(message){let t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
document.querySelectorAll('.category-card').forEach(x=>x.onclick=()=>{document.querySelector('.category-card.selected').classList.remove('selected');x.classList.add('selected');toast(`${x.querySelector('strong').textContent} shops near you`) });document.querySelector('#newList').onclick=()=>toast('A new shopping list is ready to name.');document.querySelector('.checkout').onclick=()=>toast('Checkout is ready — delivery and handling are ₹0.');document.querySelector('#searchButton').onclick=()=>{let q=document.querySelector('#searchInput').value.trim();if(q){location.hash='compare';toast(`Showing nearby results for “${q}”`)}};
// Archived initial visual sketch; live application code is in src/.
